from pathlib import Path
import json,random,hashlib,sys
sys.stdout.reconfigure(encoding='utf8')
HERE=Path(__file__).resolve().parents[2]/'tmp'/'suficiencia-build';passages=[];questions=[]

def item(skill,prompt,answer,wrong,reason):return (skill,prompt,answer,wrong,reason)
def read(slug,title,text,pages,section,items,chapter=1):
 assert len(items)==5
 pid='lectura-ampliada-'+slug
 source={'document':'Anatomía y fisiología: la unidad entre forma y función','author':'Kenneth S. Saladin','edition':'6.ª edición','chapter':f'{chapter}. '+('Temas principales de anatomía y fisiología' if chapter==1 else 'La química de la vida'),'section':section,'pdfPages':pages,'printedPages':[p-28 for p in pages],'kind':'adaptación didáctica para lectura comprensiva','original':False}
 passages.append({'id':pid,'title':title,'text':text,'source':source})
 for k,(skill,prompt,answer,wrong,reason) in enumerate(items,1):
  qid=f'{pid}-{k}';options=[answer,*wrong]
  assert len(options)==4 and len(set(options))==4,(qid,options)
  random.Random(qid).shuffle(options)
  questions.append({'id':qid,'subject':'lectura','topic':skill,'passageId':pid,'text':prompt,'options':options,'correct':options.index(answer),'explanation':reason,'source':source})

read('forma-funcion','Dos preguntas sobre el mismo cuerpo',
'Estudiar el cuerpo permite formular dos preguntas relacionadas: cómo está organizado y qué hace cada una de sus partes. La anatomía se ocupa de la estructura; la fisiología, de la función. Separarlas puede resultar útil para ordenar una explicación, pero no significa que el organismo presente ambas como realidades independientes. Una estructura despierta el interés por su actividad, y una actividad exige conocer las estructuras que la hacen posible.\n\nPor eso, identificar una parte corporal no agota su estudio. El nombre y la localización ofrecen un punto de partida; comprender su funcionamiento da sentido a esa descripción. A la inversa, una explicación funcional sin referencia a la organización del cuerpo quedaría incompleta. El vínculo entre forma y función permite relacionar los detalles que se aprenden y constituye una base para estudiar las ciencias de la salud.',[30],'El ámbito de la anatomía y la fisiología',[
item('Idea principal','¿Qué idea organiza la lectura?','La estructura y la función se comprenden de manera complementaria.',['Aprender nombres vuelve innecesario estudiar funciones.','La anatomía y la fisiología estudian organismos diferentes.','La función explica por sí sola toda la estructura.'],'Los dos párrafos relacionan las preguntas por la organización y la actividad del mismo cuerpo.'),
item('Información explícita','¿De qué se ocupa la anatomía en esta lectura?','De la estructura corporal.',['De los nombres sin localización.','Exclusivamente de la actividad de los órganos.','Solo de las enfermedades.'],'El primer párrafo asigna de forma directa la estructura a la anatomía y la función a la fisiología.'),
item('Inferencia','¿Qué forma de estudiar sería coherente con el texto?','Relacionar la localización de una parte con lo que realiza.',['Memorizar una ubicación y evitar preguntar su utilidad.','Estudiar funciones sin identificar estructuras.','Considerar independientes los detalles de cada disciplina.'],'Si las preguntas son complementarias, vincular sus respuestas permite comprender mejor el conjunto.'),
item('Vocabulario en contexto','En «no agota su estudio», ¿qué significa «agota»?','Completa por entero.',['Produce cansancio físico.','Elimina del cuerpo.','Vuelve más breve.'],'El pasaje afirma que identificar una parte no completa todo lo que puede conocerse sobre ella.'),
item('Relación entre ideas','¿Qué función cumple «A la inversa»?','Introducir la dependencia de la función respecto de la estructura.',['Negar lo dicho sobre la anatomía.','Cambiar a un tema sin relación.','Presentar una lista de partes corporales.'],'La expresión invierte la dirección de la relación: primero se habla del significado funcional de una estructura y luego de la base estructural de una función.')])

read('exploracion','Observar no es la única manera de examinar',
'La revisión del cuerpo no depende de un único sentido. La observación visual aporta información sobre su aspecto; la palpación permite percibir estructuras con las manos, como al tomar el pulso. La auscultación consiste en escuchar sonidos que el cuerpo produce, entre ellos los del corazón y los pulmones. En la percusión se dan pequeños golpes y se atiende tanto a la resistencia encontrada como al sonido emitido.\n\nEstas técnicas se distinguen por la forma de obtener información, no por una supuesta competencia entre ellas. Examinar significa elegir y combinar medios de observación adecuados al propósito. Por ejemplo, escuchar un sonido no es lo mismo que sentir una estructura, aunque ambos procedimientos se dirijan a una misma persona. Reconocer esas diferencias evita llamar a todas las maniobras simplemente «mirar» y permite describir con mayor precisión qué se hizo durante una exploración.',[30],'Anatomía: el estudio de la forma',[
item('Idea principal','¿Cuál es el propósito central del texto?','Distinguir formas de obtener información en una exploración.',['Mostrar que la vista reemplaza a los demás sentidos.','Ordenar las técnicas desde la mejor hasta la peor.','Explicar exclusivamente los sonidos pulmonares.'],'Se describen cuatro procedimientos y luego se explica por qué conviene diferenciarlos.'),
item('Información explícita','¿Qué procedimiento emplea las manos para percibir estructuras?','La palpación.',['La auscultación.','La observación exclusivamente visual.','La escucha de sonidos naturales.'],'La definición de palpación aparece en el primer párrafo y se ejemplifica con el pulso.'),
item('Inferencia','Si alguien escucha sonidos naturales del tórax, ¿qué está realizando?','Auscultación.',['Palpación, porque toda exploración usa las manos.','Percusión, aunque no produzca golpes.','Solo observación visual.'],'La característica relevante es escuchar sonidos producidos por el cuerpo, que corresponde a la auscultación.'),
item('Vocabulario en contexto','¿Qué significa «maniobras» en el último enunciado?','Procedimientos de exploración.',['Opiniones sobre un diagnóstico.','Movimientos destinados a confundir.','Resultados de laboratorio.'],'La palabra se refiere a las acciones que se acaban de describir: observar, palpar, escuchar o percutir.'),
item('Relación entre ideas','¿Para qué se contraponen escuchar y sentir?','Para mostrar que técnicas dirigidas a una persona pueden obtener información de maneras distintas.',['Para afirmar que solo una puede ser correcta.','Para concluir que no deben combinarse.','Para explicar la composición química del sonido.'],'El contraste concreta la tesis del segundo párrafo: no todas las formas de examinar son equivalentes.')])

read('escala','El detalle cambia la pregunta',
'La anatomía macroscópica estudia estructuras que pueden apreciarse a simple vista, mediante observación, disección o imágenes. Sin embargo, hay preguntas que requieren otro nivel de detalle. Al examinar tejidos al microscopio se ingresa en la histología; al estudiar células individuales se habla de citología. Cuando la observación de tejidos busca signos de enfermedad, recibe el nombre de histopatología.\n\nEstos campos no se distinguen porque unos pertenezcan a un cuerpo distinto, sino por la escala y la finalidad de su examen. Una descripción visible de un órgano puede complementarse con el estudio de sus tejidos y células. Cambiar de escala revela relaciones que antes no podían reconocerse. Por eso, disponer de una vista general no vuelve innecesario el microscopio, del mismo modo que un detalle microscópico no siempre reemplaza la visión del órgano como conjunto.',[31],'Anatomía macroscópica e histología',[
item('Idea principal','¿Qué sostiene la lectura?','El estudio corporal usa distintas escalas y finalidades que pueden complementarse.',['La histología estudia únicamente órganos visibles.','Toda observación debe realizarse al mismo aumento.','La citología vuelve inútil la descripción de órganos.'],'La lectura vincula cada campo con su nivel de observación y cierra destacando su complementariedad.'),
item('Información explícita','¿Qué campo busca signos de enfermedad en los tejidos?','La histopatología.',['La citología por definición exclusiva.','La anatomía macroscópica solamente.','La observación sin instrumentos.'],'El texto define la histopatología por la observación de tejidos dirigida a encontrar enfermedad.'),
item('Inferencia','¿Qué puede aportar un cambio de escala?','Reconocer relaciones que no se distinguían en una vista general.',['Garantizar que toda descripción anterior era falsa.','Eliminar la necesidad de estudiar otras escalas.','Convertir un tejido en un órgano diferente.'],'El segundo párrafo explica que aumentar el detalle permite advertir relaciones antes no reconocibles.'),
item('Vocabulario en contexto','En esta lectura, «escala» se refiere a:','Nivel de detalle de la observación.',['Orden de gravedad de una enfermedad.','Cantidad de órganos presentes.','Distancia que recorre una célula.'],'Las escalas comparadas son la vista general, los tejidos y las células.'),
item('Relación entre ideas','¿Qué relación establece la última oración?','Reconoce límites tanto de la visión general como del detalle aislado.',['Declara superior a la vista general en todas las situaciones.','Restringe el microscopio al estudio de cadáveres.','Afirma que una escala debe sustituir definitivamente a la otra.'],'La construcción «del mismo modo» muestra que ambas perspectivas tienen utilidad y límites.')])

read('comparacion','Comparar para comprender funciones',
'La fisiología estudia el funcionamiento del organismo mediante métodos experimentales. Parte de lo que se sabe sobre la función humana procede de comparar cómo otras especies resuelven problemas vitales, como la respiración o el equilibrio del agua. Este enfoque recibe el nombre de fisiología comparada. Las semejanzas ofrecen una base para investigar, pero su utilidad no convierte automáticamente en idénticos a todos los organismos.\n\nLa comparación adquiere sentido cuando se relaciona con la pregunta que se desea responder. No basta elegir cualquier especie y dar por hecho que sus respuestas describen las de otra. El estudio comparado ha contribuido al desarrollo de medicamentos y procedimientos, y al aprendizaje de técnicas antes de aplicarlas en seres humanos. Su valor se encuentra en ofrecer información pertinente para investigar funciones; no en borrar la diferencia entre la especie examinada y aquella sobre la que se quieren obtener conclusiones.',[31,38],'Fisiología comparada y modelos de investigación',[
item('Idea principal','¿Qué expresa mejor la tesis del texto?','Comparar especies aporta información funcional sin hacerlas idénticas.',['La fisiología solo puede estudiar seres humanos.','Cualquier especie responde igual a todas las preguntas.','La comparación reemplaza la investigación experimental.'],'El pasaje reconoce el valor de las semejanzas y, a la vez, limita la equivalencia entre especies.'),
item('Información explícita','¿Qué ejemplo de problema vital se menciona?','El equilibrio del agua.',['La escritura de términos médicos.','La fabricación de microscopios.','La elaboración de atlas.'],'El equilibrio del agua aparece junto con la respiración como ejemplo de función comparada.'),
item('Inferencia','¿Qué conviene considerar al elegir una especie de estudio?','Su pertinencia para la pregunta que se investiga.',['Que sea diferente en todo aspecto del organismo de interés.','Que permita evitar toda evaluación posterior.','Únicamente que esté disponible.'],'El segundo párrafo condiciona el sentido de la comparación a la pregunta de investigación.'),
item('Vocabulario en contexto','¿Qué significa «pertinente» en la conclusión?','Adecuada y relacionada con el problema.',['Abundante, aunque no guarde relación.','Definitiva para cualquier especie.','Exclusiva de observaciones visuales.'],'Una información pertinente es aquella que ayuda a investigar la función o pregunta en cuestión.'),
item('Relación entre ideas','¿Para qué se menciona el desarrollo de procedimientos?','Para ejemplificar una utilidad de la fisiología comparada.',['Para afirmar que ya no se requieren estudios humanos.','Para negar las diferencias entre especies.','Para cambiar a una descripción anatómica sin relación.'],'El ejemplo muestra una aplicación del enfoque cuyo alcance ya se ha delimitado.')])

read('autoridad','Seguir un consejo y cuestionar un libro',
'Galeno elaboró explicaciones sobre anatomía a partir de los medios de observación disponibles en su época. Como no podía estudiar libremente cadáveres humanos, recurrió a la disección de otros animales y trasladó algunas observaciones al ser humano. Parte de esas deducciones fue incorrecta. No obstante, sostuvo que la ciencia debía ser un método de descubrimiento y advirtió que incluso sus propios libros podían contener errores.\n\nLa paradoja aparece en la conducta de seguidores que aceptaron sus escritos sin discutirlos. Al conservar las afirmaciones como verdades intocables, desatendieron el consejo de confiar en la observación. Así, respetar a un autor no equivale necesariamente a repetir todas sus conclusiones. En el caso descrito, tomar en serio su propuesta habría exigido revisar lo que afirmaba cuando las pruebas lo justificaran. La fidelidad a una forma de investigar puede requerir corregir los resultados de quien la defendió.',[32],'El legado de griegos y romanos',[
item('Idea principal','¿Qué paradoja desarrolla el texto?','Al aceptar sin revisión a Galeno, sus seguidores desobedecieron su consejo de observar.',['Galeno prohibió que se corrigieran sus libros.','Los seguidores prefirieron siempre pruebas nuevas a los escritos.','La disección animal permitió eliminar todos los errores.'],'La oposición central está entre el valor de la observación defendido por Galeno y la aceptación dogmática de su obra.'),
item('Información explícita','¿Qué limitación influyó en algunas deducciones de Galeno?','La restricción para estudiar cadáveres humanos.',['La ausencia de escritos anteriores.','La prohibición de observar animales.','La decisión de no atender ninguna herida.'],'El primer párrafo explica que la limitación de acceso lo llevó a usar observaciones de otros animales.'),
item('Inferencia','¿Qué conducta habría seguido mejor su consejo?','Revisar una afirmación del libro si la observación la contradecía.',['Conservar toda afirmación por respeto al nombre del autor.','Evitar observar para no discrepar.','Rechazar todos los libros antes de leerlos.'],'La fidelidad al método de descubrimiento permite corregir conclusiones apoyándose en pruebas.'),
item('Vocabulario en contexto','¿Qué significa «intocables» referido a las verdades?','Que no se permite cuestionarlas.',['Que no pueden percibirse con las manos.','Que solo pueden explicarse mediante imágenes.','Que carecen de autor conocido.'],'El adjetivo describe una actitud dogmática ante las afirmaciones, no una propiedad física.'),
item('Relación entre ideas','¿Qué función cumple la última oración?','Generalizar la lección del caso histórico.',['Añadir una nueva técnica de disección.','Negar que los seguidores leyeran los libros.','Afirmar que todas las conclusiones eran falsas.'],'La conclusión pasa del ejemplo de Galeno a la diferencia entre seguir un método y repetir resultados.')])

read('vesalio','Bajar de la cátedra',
'En ciertas clases antiguas de anatomía, el profesor leía un libro desde una posición elevada mientras otra persona manipulaba el cadáver. La enseñanza quedaba dividida entre quien exponía la autoridad escrita y quien realizaba el trabajo manual. Vesalius rompió esa práctica al efectuar las disecciones por sí mismo. El contacto directo con las estructuras le permitió advertir discrepancias entre lo observado y algunas descripciones heredadas.\n\nEl cambio no consistió únicamente en que una persona ocupara un lugar distinto en el aula. Modificó la relación entre la explicación y la observación que podía sostenerla o corregirla. Sus ilustraciones anatómicas buscaron representar con precisión aquello que se estudiaba y sirvieron para enseñar. La escena de descender de la cátedra resume, por ello, una transformación intelectual: la autoridad de un texto debía confrontarse con el cuerpo examinado, y la imagen podía convertirse en un instrumento de conocimiento.',[33],'El nacimiento de la medicina moderna',[
item('Idea principal','¿Qué cambio destaca la lectura?','La integración de enseñanza, observación directa y representación precisa.',['La sustitución de toda observación por lecturas en voz alta.','La separación definitiva del profesor del trabajo anatómico.','La preferencia por imágenes decorativas sobre estructuras.'],'La lectura presenta la disección y la ilustración como medios para contrastar y comunicar conocimiento.'),
item('Información explícita','¿Qué hizo Vesalius según el primer párrafo?','Realizó las disecciones personalmente.',['Delegó toda observación en quien leía.','Prohibió comparar el cuerpo con los libros.','Usó las imágenes solo para decorar.'],'El pasaje identifica esa participación directa como la ruptura con la práctica descrita.'),
item('Inferencia','¿Por qué observar podía llevar a corregir un texto?','Porque permitía encontrar discrepancias con sus descripciones.',['Porque cualquier imagen era necesariamente falsa.','Porque el trabajo manual no producía información.','Porque la posición elevada impedía leer.'],'El vínculo entre observación y corrección aparece en las discrepancias señaladas al final del primer párrafo.'),
item('Vocabulario en contexto','¿Qué significa «confrontarse» en este caso?','Compararse críticamente.',['Destruirse físicamente.','Aprenderse de memoria.','Ocultarse ante el público.'],'Se trata de contrastar la descripción escrita con la estructura observada.'),
item('Relación entre ideas','¿Qué representa la escena de bajar de la cátedra?','Un ejemplo concreto de un cambio en la forma de conocer.',['Una recomendación sobre el mobiliario de todas las aulas.','La renuncia a enseñar anatomía.','Una disputa sin consecuencias para el conocimiento.'],'El segundo párrafo interpreta la acción física como síntesis de una transformación intelectual.')])

read('circulacion','Cuando una explicación necesita revisión',
'Una antigua explicación sostenía que la sangre se producía a partir del alimento y terminaba siendo consumida por los órganos. Los estudios de William Harvey contribuyeron a reemplazar esa idea por otra: la sangre circula desde el corazón hacia el cuerpo y regresa a él. El cambio afectaba la manera de comprender el movimiento sanguíneo, no solo el nombre de una estructura.\n\nLa propuesta encontró resistencia entre quienes estaban apegados a la interpretación anterior. Sin embargo, la aceptación social y la calidad de una explicación no son lo mismo. El trabajo de Harvey es presentado como un paso importante hacia la fisiología experimental porque buscó investigar cómo funciona el cuerpo. La controversia permite reconocer que una idea puede ser defendida por costumbre y aun así requerir revisión. También recuerda que estudiar funciones exige relacionar observaciones con una explicación capaz de darles sentido.',[33],'William Harvey y la fisiología experimental',[
item('Idea principal','¿Cuál es el eje del pasaje?','La revisión de una explicación sobre la sangre mediante el estudio de su funcionamiento.',['La creación de un nuevo nombre para el corazón.','La aceptación inmediata de toda propuesta nueva.','La utilidad de conservar creencias por costumbre.'],'El contraste entre consumo y circulación muestra un cambio explicativo basado en investigar la función.'),
item('Información explícita','¿Qué ocurre con la sangre en la explicación atribuida a Harvey?','Sale del corazón y regresa a él.',['Es consumida por completo en cada órgano.','Se detiene definitivamente al llegar al cuerpo.','Solo se observa fuera del organismo.'],'La circulación se describe como un recorrido con retorno, a diferencia de la idea previa.'),
item('Inferencia','¿Qué demuestra la resistencia de algunos contemporáneos?','Que el apego a una explicación puede dificultar su revisión.',['Que toda idea antigua es necesariamente correcta.','Que Harvey no estudió funciones.','Que una explicación se valida por su popularidad.'],'El pasaje vincula esa resistencia con la costumbre y separa aceptación social de calidad explicativa.'),
item('Vocabulario en contexto','En «estaban apegados», la expresión significa:','Mantenían una fuerte adhesión.',['Se encontraban físicamente unidos.','Habían olvidado por completo.','Estaban obligados a investigar.'],'Se describe la adhesión de los contemporáneos a una interpretación heredada.'),
item('Relación entre ideas','¿Para qué sirve la última oración?','Relacionar el caso histórico con una exigencia del estudio funcional.',['Introducir una enfermedad no mencionada.','Indicar que los nombres reemplazan los experimentos.','Afirmar que no hacen falta observaciones.'],'La conclusión vincula investigar funciones con explicar lo que se observa.')])

read('microscopios','Un instrumento más simple no siempre muestra menos',
'El microscopio compuesto de Hooke utilizaba una lente cerca de la muestra y otra cerca del ojo. Leeuwenhoek, en cambio, trabajó con un instrumento de una sola lente. A pesar de su diseño más simple, este último logró una ampliación muy útil gracias a la calidad de fabricación de sus lentes. El número de componentes, por sí solo, no permite anticipar cuánto podrá observarse.\n\nAmbos investigadores ampliaron el campo de la biología al examinar estructuras que no se reconocían a simple vista. Más adelante, otros avances ópticos mejoraron las imágenes, que en los primeros instrumentos podían presentar bordes borrosos y distorsiones de color. La historia de estos aparatos muestra una relación entre posibilidades técnicas y preguntas científicas. No basta disponer de un instrumento llamativo: importa qué detalle permite distinguir y qué observaciones confiables pueden realizarse con él.',[33,34],'Hooke, Leeuwenhoek y la microscopia',[
item('Idea principal','¿Qué conclusión articula la lectura?','La utilidad de un instrumento depende de lo que permite observar, no solo de su complejidad.',['Toda lente única es superior a cualquier sistema compuesto.','Agregar componentes garantiza imágenes sin defectos.','Los primeros microscopios ya carecían de limitaciones.'],'El texto compara diseños y subraya la calidad de la observación como criterio de utilidad.'),
item('Información explícita','¿Qué ventaja se atribuye a las lentes de Leeuwenhoek?','La calidad de su fabricación.',['La presencia de dos oculares.','La ausencia de cualquier aumento.','La capacidad de observar sin muestra.'],'La primera parte explica con esa calidad el desempeño del instrumento simple.'),
item('Inferencia','¿Qué afirmación se puede inferir?','Una mayor cantidad de piezas no garantiza una observación mejor.',['Todos los aparatos simples ofrecen el mismo aumento.','La calidad óptica es irrelevante.','Las distorsiones favorecen la observación precisa.'],'La comparación entre un instrumento compuesto y uno de una sola lente contradice esa garantía automática.'),
item('Vocabulario en contexto','¿Qué significa «distorsiones» en el pasaje?','Alteraciones de la imagen observada.',['Nuevas partes de la muestra.','Cambios en la pregunta del investigador.','Movimientos de una lente entre dos lugares.'],'Los bordes borrosos y los cambios de color se presentan como defectos en la imagen.'),
item('Relación entre ideas','¿Qué aportan los ejemplos de bordes borrosos y color?','Ilustran limitaciones que motivaron mejoras ópticas.',['Prueban que no se observó ninguna estructura.','Muestran que toda mejora fue innecesaria.','Describen la composición química de los tejidos.'],'Los ejemplos explican por qué los instrumentos requirieron perfeccionamiento.')])

read('ciencia-cooperativa','La investigación como empresa compartida',
'Bacon y Descartes imaginaron una ciencia más amplia que la actividad de unos pocos estudiosos aislados. Defendieron una empresa pública y cooperativa, sostenida por comunidades de investigación. Aunque no compartieron todas sus ideas, coincidieron en la importancia de nuevos hábitos de pensamiento y de una actividad científica organizada.\n\nLa contribución descrita no se reduce a descubrir una estructura o inventar un aparato. Incluye proponer maneras de buscar información confiable y de cooperar para obtenerla. Observar con cuidado, razonar de forma lógica y analizar honestamente las conclusiones son hábitos que no pertenecen a un único procedimiento de laboratorio. Por eso, hablar de método científico no obliga a imaginar una receta idéntica para todos los problemas. Se trata también de una disciplina intelectual que permite formular preguntas, valorar las pruebas y someter las propias afirmaciones al examen de otros.',[35],'El método científico',[
item('Idea principal','¿Qué idea resume el texto?','La ciencia requiere organización cooperativa y hábitos rigurosos de pensamiento.',['La ciencia solo avanza mediante aparatos nuevos.','Todos los problemas exigen una receta experimental idéntica.','Bacon y Descartes coincidieron en cada una de sus opiniones.'],'El pasaje combina la dimensión colectiva de la ciencia con sus hábitos de observación y razonamiento.'),
item('Información explícita','¿En qué coincidían los pensadores mencionados?','En favorecer una actividad científica organizada y cooperativa.',['En rechazar toda comunidad de estudiosos.','En que investigar era una tarea exclusivamente privada.','En que observar no tenía importancia.'],'El primer párrafo presenta esa coincidencia pese a otras diferencias.'),
item('Inferencia','¿Qué podría aportar alguien sin inventar un aparato?','Una forma más rigurosa de organizar y evaluar la investigación.',['Nada que pueda influir en la ciencia.','La eliminación de toda crítica externa.','Una garantía de que sus conclusiones serán definitivas.'],'El segundo párrafo reconoce como contribución los hábitos y modos de búsqueda, además de los descubrimientos materiales.'),
item('Vocabulario en contexto','¿Qué significa «disciplina intelectual»?','Práctica cuidadosa y ordenada del pensamiento.',['Una sanción aplicada a los investigadores.','Una única técnica para todo laboratorio.','La memorización sin análisis de afirmaciones.'],'La expresión alude a razonar, observar y valorar pruebas con rigor.'),
item('Relación entre ideas','¿Qué corrige la comparación con una «receta»?','La idea de que el método científico es un procedimiento idéntico para cualquier problema.',['La necesidad de razonar con lógica.','El valor de trabajar con otras personas.','La posibilidad de formular preguntas.'],'El texto admite variación de procedimientos y resalta hábitos que orientan la investigación.')])

read('induccion','De muchas observaciones a una generalización',
'Observar un solo caso puede despertar una pregunta, pero no basta siempre para describir lo habitual. El método inductivo reúne observaciones y busca en ellas semejanzas, diferencias y tendencias. A partir de ese conjunto se proponen generalizaciones y predicciones. La descripción de la estructura corporal normal, por ejemplo, se apoya en el examen de muchos cuerpos y no únicamente de uno.\n\nLa confianza en una conclusión aumenta cuando los procedimientos son confiables y los resultados se confirman repetidamente. Sin embargo, esa confianza no convierte lo aprendido en una afirmación inmune a cualquier revisión. La investigación conserva la posibilidad de corregir una generalización si aparece una observación creíble que la contradiga. El contraste no es entre saber y no saber nada, sino entre una confianza apoyada en pruebas y una certeza que se niega a examinarlas. Aprender mediante inducción exige reunir evidencia y mantener abierta su interpretación.',[35],'El método inductivo',[
item('Idea principal','¿Cuál es la idea principal?','Las generalizaciones inductivas se apoyan en observaciones y siguen abiertas a revisión.',['Una observación aislada siempre describe todos los casos.','La repetición vuelve innecesario valorar la calidad de los métodos.','Toda conclusión revisable carece de valor.'],'El texto relaciona la acumulación de evidencia con una confianza que no excluye la corrección.'),
item('Información explícita','¿En qué se apoya la descripción de la estructura corporal normal?','En observaciones de muchos cuerpos.',['En un único cuerpo elegido al azar.','En la ausencia de diferencias entre las personas.','En afirmaciones que no requieren observación.'],'El ejemplo del primer párrafo explica el tipo de base observacional de esa descripción.'),
item('Inferencia','¿Qué hacer ante una observación creíble que contradice una generalización?','Considerar su revisión.',['Descartarla solo porque es nueva.','Prohibir nuevas observaciones.','Concluir que observar carece de utilidad.'],'El segundo párrafo exige conservar la posibilidad de corregir la conclusión.'),
item('Vocabulario en contexto','En «inmune a cualquier revisión», «inmune» significa:','Exenta de ser cuestionada.',['Protegida por células defensivas.','Aceptada únicamente en biología.','Carente de observaciones repetidas.'],'Se usa figuradamente para referirse a afirmaciones que se pretenden fuera de todo examen.'),
item('Relación entre ideas','¿Qué función cumple el contraste entre confianza y certeza cerrada?','Mostrar que una conclusión puede ser sólida sin volverse dogmática.',['Equiparar la investigación con la ausencia total de conocimiento.','Negar que puedan encontrarse tendencias.','Sustituir la evidencia por una opinión personal.'],'El contraste evita confundir la revisión posible con la falta absoluta de fundamentos.')])

read('muestras','El tamaño de una prueba',
'Las personas no responden de manera idéntica a una misma intervención. Por eso, un resultado observado en muy pocos sujetos puede depender de variaciones individuales o de acontecimientos azarosos. En el diseño de un estudio, el tamaño de la muestra es el número de sujetos incluidos. Considerarlo forma parte del esfuerzo por obtener resultados en los que pueda depositarse confianza.\n\nUn tamaño adecuado ayuda a controlar la influencia de esas variaciones, pero no es el único aspecto que importa. El experimento también requiere comparaciones apropiadas y cuidado frente a las expectativas de participantes e investigadores. Aumentar el número de observaciones no autoriza a ignorar cómo fueron obtenidas. La lectura de un resultado necesita, por tanto, una mirada conjunta al tamaño y al diseño de la prueba. Una cifra grande no reemplaza por sí sola las decisiones que permiten interpretar lo observado.',[36],'Diseño de experimentos: tamaño de muestra',[
item('Idea principal','¿Qué plantea la lectura?','El tamaño de la muestra contribuye a la confianza, junto con otros cuidados del diseño.',['Una muestra grande corrige cualquier defecto del experimento.','Las diferencias individuales impiden toda investigación.','El tamaño de muestra equivale a la duración del estudio.'],'Se define la muestra y luego se delimita lo que su tamaño puede y no puede aportar.'),
item('Información explícita','¿Cómo se define el tamaño de la muestra?','Como el número de sujetos incluidos.',['Como la cantidad de días de observación.','Como el tamaño corporal de cada sujeto.','Como la diferencia entre dos tratamientos.'],'La definición aparece en el primer párrafo.'),
item('Inferencia','¿Qué pregunta sería útil ante un estudio muy grande?','Cómo se obtuvieron y compararon sus observaciones.',['Por qué ya no necesita ningún control.','Cómo evitar revisar sus métodos.','Por qué todos sus resultados deben ser idénticos.'],'La segunda parte advierte que una cifra grande no sustituye la calidad del diseño.'),
item('Vocabulario en contexto','¿Qué quiere decir «azarosos»?','Que pueden depender de la casualidad.',['Que siempre son provocados deliberadamente.','Que son iguales en todos los participantes.','Que no se pueden observar.'],'El término se contrapone al efecto que se desea estudiar y señala variaciones debidas al azar.'),
item('Relación entre ideas','¿Qué función cumple «pero no es el único aspecto»?','Limitar una interpretación excesiva del valor del tamaño.',['Negar por completo el valor de incluir sujetos.','Cambiar de tema hacia la anatomía.','Afirmar que todo tamaño es adecuado.'],'La oración reconoce una contribución y evita presentarla como garantía suficiente.')])

read('probabilidad','Una diferencia no se interpreta sola',
'Dos grupos de un experimento pueden terminar con resultados diferentes. La diferencia, considerada de manera aislada, no permite decidir automáticamente si se debe al tratamiento o a la variación aleatoria. Por esa razón se emplean procedimientos estadísticos que ayudan a valorar la confiabilidad de los datos. El resultado científico se expresa con un grado de confianza, no como una garantía absoluta que elimina toda incertidumbre.\n\nEsta precaución no significa que todas las explicaciones tengan el mismo apoyo. Significa que la fuerza de una conclusión debe relacionarse con la evidencia y con la manera de analizarla. Una afirmación prudente puede estar mejor fundada que una frase rotunda que omite sus condiciones. Al leer una investigación conviene preguntar qué diferencia se encontró, qué comparación se hizo y qué tan razonable es atribuir el resultado al factor estudiado. Los números adquieren significado dentro de ese razonamiento.',[36,37],'Diseño de experimentos y análisis estadístico',[
item('Idea principal','¿Qué idea desarrolla el texto?','Las diferencias experimentales requieren análisis y conclusiones ajustadas a la evidencia.',['Cualquier diferencia prueba por sí sola la eficacia de un tratamiento.','La incertidumbre hace equivalentes todas las explicaciones.','Los números no pueden ayudar a investigar.'],'El pasaje explica por qué observar diferencias no basta y resalta el análisis de su confiabilidad.'),
item('Información explícita','¿Qué alternativa al efecto del tratamiento se menciona?','La variación aleatoria.',['El cambio de nombre del experimento.','La desaparición de los grupos comparados.','La ausencia de cualquier resultado.'],'El primer párrafo presenta expresamente esa posibilidad como motivo de análisis.'),
item('Inferencia','¿Por qué una afirmación prudente podría estar mejor fundada?','Porque expresa su alcance de acuerdo con las pruebas.',['Porque evita usar datos.','Porque nunca permite sacar conclusiones.','Porque una frase rotunda siempre es falsa.'],'La prudencia descrita consiste en adecuar la fuerza de la afirmación al apoyo que realmente tiene.'),
item('Vocabulario en contexto','En la lectura, «rotunda» significa:','Categórica y sin matices.',['Circular en su forma.','Estadísticamente demostrada por definición.','Basada necesariamente en comparaciones apropiadas.'],'El término describe una forma de afirmar que puede omitir condiciones o incertidumbre.'),
item('Relación entre ideas','¿Qué aportan las preguntas de la última parte?','Orientan una lectura crítica de los resultados.',['Reemplazan los resultados con opiniones sin evidencia.','Proponen memorizar solo cifras.','Aseguran que toda diferencia es aleatoria.'],'Las preguntas concretan el razonamiento necesario para interpretar diferencias experimentales.')])

read('replicacion','Después de publicar',
'Publicar una investigación no la retira del examen de la comunidad científica. Antes de aparecer, un trabajo puede recibir una evaluación crítica de especialistas; después, otros investigadores pueden intentar reproducir sus resultados. Esa continuidad del examen es importante cuando los hallazgos tienen gran relevancia o se apartan de lo esperado.\n\nReproducir no significa limitarse a repetir una conclusión escrita. Consiste en comprobar si, al investigar el fenómeno, se encuentran resultados que apoyan lo informado. La revisión y la reproducción cumplen funciones relacionadas, aunque no idénticas: una examina críticamente el trabajo presentado y la otra vuelve a poner a prueba sus resultados. El conocimiento se fortalece cuando puede ser evaluado por personas distintas de sus autores. Así, la publicación es parte del recorrido de una afirmación científica, y no una frontera después de la cual deja de admitir preguntas.',[37],'La revisión científica externa',[
item('Idea principal','¿Qué sostiene el texto?','La evaluación científica continúa después de publicar un trabajo.',['La publicación convierte cualquier resultado en definitivo.','Reproducir consiste en citar el mismo artículo.','Solo el autor puede valorar sus resultados.'],'La lectura presenta revisión y reproducción como partes de un examen continuo.'),
item('Información explícita','¿Qué pueden hacer otros investigadores después de una publicación?','Intentar reproducir sus resultados.',['Modificar retroactivamente todos los datos del autor.','Impedir cualquier nueva pregunta.','Dar por terminada toda investigación relacionada.'],'La primera parte menciona de manera expresa la reproducción posterior de resultados.'),
item('Inferencia','¿Qué actitud sería contraria a la lectura?','Rechazar todo examen posterior porque el artículo ya fue publicado.',['Pedir que otros valoren el trabajo.','Revisar críticamente un manuscrito.','Comparar nuevos resultados con los informados.'],'La conclusión niega que publicar cierre la posibilidad de formular preguntas.'),
item('Vocabulario en contexto','¿Qué significa «frontera» en la última oración?','Límite que supuestamente pondría fin al examen.',['Lugar geográfico donde se hizo el experimento.','Diferencia entre dos países.','Instrumento empleado para medir.'],'Se usa como imagen de un límite, y el texto rechaza que la publicación cumpla esa función.'),
item('Relación entre ideas','¿Cómo se relacionan revisión y reproducción?','Son complementarias, pero no realizan exactamente la misma tarea.',['Son palabras idénticas para citar conclusiones.','Se excluyen de manera necesaria.','Solo pueden efectuarse antes de publicar.'],'El segundo párrafo distingue evaluar el trabajo de volver a poner a prueba sus resultados.')])

read('historia-evolutiva','Comprender una forma exige conocer su historia',
'Una descripción del cuerpo puede indicar cómo es una estructura sin explicar por qué llegó a tener esa forma. La perspectiva evolutiva añade una dimensión histórica: las características actuales proceden de cambios en poblaciones a lo largo de generaciones. Esta mirada no reemplaza el estudio de la anatomía o de la función, sino que permite relacionarlos con el pasado del organismo.\n\nEl libro presenta la selección natural y la teoría celular como dos ideas especialmente importantes para comprender la biología humana. La primera ayuda a explicar cambios y adaptaciones; la segunda orienta la comprensión de las funciones hacia la actividad de las células. Son perspectivas diferentes que pueden colaborar en una misma investigación. Conocer una estructura, describir lo que hace y considerar su historia no son tareas rivales. Reunidas, permiten formular preguntas que una descripción aislada quizá no habría sugerido.',[37,38,50],'Orígenes y adaptaciones; repaso de temas principales',[
item('Idea principal','¿Qué aporta la perspectiva evolutiva según el pasaje?','Una dimensión histórica que complementa la descripción y la función.',['La sustitución de todo estudio celular.','Una lista de nombres sin relaciones.','La idea de que las estructuras carecen de pasado.'],'El primer párrafo presenta la historia como un complemento de las otras preguntas biológicas.'),
item('Información explícita','¿Qué dos ideas importantes menciona el texto?','La selección natural y la teoría celular.',['La percusión y la auscultación.','La histología y el origen de las palabras.','La tensión superficial y el pH.'],'Estas dos perspectivas se nombran al inicio del segundo párrafo.'),
item('Inferencia','¿Qué pregunta incorpora mejor la dimensión histórica?','Cómo llegó a establecerse una característica a lo largo de generaciones.',['Cuál es únicamente el nombre actual de una parte.','Qué tamaño tiene hoy un órgano, sin otra consideración.','Qué palabra se escribe en una etiqueta.'],'La dimensión histórica se refiere a procesos de cambio en poblaciones y generaciones.'),
item('Vocabulario en contexto','¿Qué significa «rivales» en la conclusión?','Que se oponen y compiten entre sí.',['Que describen niveles de aumento.','Que pertenecen al mismo autor.','Que se realizan siempre en momentos distintos.'],'La lectura niega que describir, explicar funciones y considerar la historia sean tareas incompatibles.'),
item('Relación entre ideas','¿Para qué se contrastan la teoría celular y la selección natural?','Para mostrar perspectivas distintas que pueden contribuir a una misma comprensión.',['Para decidir cuál debe eliminar a la otra.','Para declarar que ambas hablan solo del pasado.','Para concluir que la anatomía no aporta preguntas.'],'El pasaje distingue sus aportes y luego subraya su colaboración.')])

read('seleccion','Ventajas que cambian una población',
'Los individuos de una especie no son iguales en todos sus rasgos. Algunas diferencias hereditarias pueden favorecer que ciertos individuos dejen más descendencia en un entorno determinado. Cuando esos rasgos se transmiten y se vuelven más frecuentes en generaciones sucesivas, cambia la composición genética de la población. Este proceso permite comprender la selección natural sin suponer que cada individuo decide transformarse.\n\nLas condiciones que favorecen unas características frente a otras reciben el nombre de presiones selectivas. Entre ellas pueden encontrarse el clima, la disponibilidad de alimentos, los depredadores o la enfermedad. Una ventaja depende de ese contexto y de su relación con el éxito reproductivo. Por eso, el cambio descrito se reconoce en la población a lo largo de generaciones. No equivale a un cambio voluntario que un organismo realiza porque necesita una característica nueva durante su propia vida.',[38,44],'Evolución, selección y adaptación',[
item('Idea principal','¿Qué explica principalmente la lectura?','Cómo diferencias hereditarias pueden cambiar una población a lo largo de generaciones.',['Cómo cada individuo elige los rasgos de sus hijos.','Por qué todas las diferencias desaparecen en un entorno.','Cómo una necesidad produce de inmediato una transformación voluntaria.'],'La secuencia une diferencias heredables, descendencia y cambio de frecuencias poblacionales.'),
item('Información explícita','¿Cuál es una presión selectiva mencionada?','La disponibilidad de alimentos.',['El nombre de una especie en un libro.','El orden de los capítulos.','La decisión consciente de cambiar los genes.'],'El texto incluye los alimentos entre las condiciones del entorno que pueden favorecer unos rasgos.'),
item('Inferencia','¿Por qué un rasgo ventajoso en un contexto no se define como ventaja absoluta?','Porque su efecto se relaciona con condiciones del entorno.',['Porque los rasgos hereditarios no se transmiten.','Porque todos los entornos son iguales.','Porque no existe diferencia en reproducción.'],'El segundo párrafo afirma que la ventaja depende del contexto y del éxito reproductivo.'),
item('Vocabulario en contexto','¿Qué significa «sucesivas»?','Que siguen unas a otras.',['Que ocurren dentro del mismo individuo.','Que no presentan descendencia.','Que aparecen sin relación temporal.'],'La palabra califica generaciones que se suceden en el tiempo.'),
item('Relación entre ideas','¿Qué aclara la última oración?','Distingue el cambio poblacional de una transformación voluntaria individual.',['Niega que haya transmisión hereditaria.','Afirma que toda presión selectiva es consciente.','Reemplaza la población por un órgano.'],'El cierre corrige una interpretación del proceso que el primer párrafo ya había descartado.')])

read('vision','Una mirada adecuada al entorno',
'Vivir entre ramas plantea dificultades distintas de las que aparecen en un espacio abierto. Moverse entre apoyos y alcanzar objetos exige coordinar lo que se ve con el movimiento. En los primates, los ojos orientados hacia el frente favorecen la visión estereoscópica, es decir, la percepción de profundidad. Esta capacidad ayuda a calcular distancias y a coordinar la mano con el ojo.\n\nLa visión de colores ofrece otra utilidad: distinguir matices puede ayudar a reconocer alimentos en diferentes condiciones. La lectura de estas características no debe separarlas del entorno en el que resultan útiles. Tampoco implica que el ser humano descienda de los simios actuales. La relación entre grupos emparentados se parece más a la de primos con antepasados compartidos que a la de un padre y su hijo. Comparar rasgos permite proponer relaciones históricas sin convertir una especie actual en el antepasado directo de otra.',[39],'Las adaptaciones básicas del ser humano como primate',[
item('Idea principal','¿Qué idea reúne las dos partes del texto?','Los rasgos visuales se interpretan en su contexto y la comparación requiere entender el parentesco.',['La visión de profundidad solo sirve para reconocer colores.','Los simios actuales son necesariamente antepasados directos humanos.','El entorno no guarda relación con la utilidad de un rasgo.'],'La primera parte relaciona visión y entorno; la segunda evita una interpretación incorrecta del parentesco.'),
item('Información explícita','¿Cómo se explica la visión estereoscópica?','Como percepción de profundidad.',['Como capacidad de oír desde ambos lados.','Como reconocimiento exclusivo de un color.','Como observación microscópica de células.'],'La definición aparece inmediatamente después del término.'),
item('Inferencia','¿Qué tarea se beneficiaría de percibir profundidad?','Estimar la distancia hasta un apoyo.',['Pronunciar un nombre científico.','Medir la masa de una molécula.','Distinguir una abreviatura de un epónimo.'],'La lectura asocia la percepción de profundidad con el cálculo de distancias y la coordinación.'),
item('Vocabulario en contexto','¿Qué son «matices» en el segundo párrafo?','Diferencias sutiles de color.',['Cambios de parentesco entre especies.','Nombres diferentes de una estructura.','Movimientos de una rama.'],'La palabra aparece en la explicación de la utilidad de la visión de colores.'),
item('Relación entre ideas','¿Para qué se usa la comparación con primos?','Para explicar antepasados compartidos sin descendencia directa entre especies actuales.',['Para afirmar que los primates carecen de semejanzas.','Para sustituir las observaciones por una genealogía individual.','Para indicar que todas las especies actuales son idénticas.'],'La analogía aclara el tipo de relación histórica que propone la lectura.')])

read('bipedestacion','Caminar cambia más que la marcha',
'Mantenerse y caminar sobre dos pies recibe el nombre de bipedestación. Entre sus ventajas se encuentra la posibilidad de observar el entorno desde una posición erguida y liberar las extremidades anteriores para otras tareas. Transportar objetos, por ejemplo, no exige que esas extremidades sostengan el cuerpo del mismo modo que al desplazarse sobre cuatro apoyos.\n\nLa adaptación a esta forma de locomoción se relaciona con varias partes del organismo, entre ellas la pelvis, los miembros inferiores, la columna y los músculos. No se reduce a que cambie una sola pieza. El texto presenta así una relación entre función y organización: una manera distinta de moverse guarda vínculo con modificaciones de un conjunto de estructuras. Comprender una adaptación requiere examinar esas relaciones y no limitarse a nombrar un rasgo aislado. El movimiento sirve aquí como entrada para estudiar al organismo como un sistema de partes vinculadas.',[39,40],'Bipedestación',[
item('Idea principal','¿Qué destaca el pasaje sobre la bipedestación?','Su relación con ventajas funcionales y cambios en varias estructuras.',['Su dependencia exclusiva de una única pieza corporal.','La imposibilidad de transportar objetos al estar erguido.','Su falta de relación con la anatomía.'],'El texto parte de las ventajas y luego explica que la adaptación compromete un conjunto de estructuras.'),
item('Información explícita','¿Qué ventaja se menciona?','Liberar las extremidades anteriores para otras tareas.',['Eliminar la necesidad de músculos.','Volver innecesario observar el entorno.','Transformar la marcha en ausencia de movimiento.'],'La ventaja se presenta en el primer párrafo y se ilustra con el transporte de objetos.'),
item('Inferencia','¿Qué estudio sería más coherente con la lectura?','Examinar cómo varias estructuras participan en la locomoción.',['Buscar una sola parte que explique por completo toda la adaptación.','Ignorar la función y memorizar nombres aislados.','Estudiar únicamente qué palabra designa la marcha.'],'La adaptación se describe como una relación entre función y varias partes del organismo.'),
item('Vocabulario en contexto','¿Qué significa «locomoción»?','Desplazamiento del organismo.',['Elaboración de tejidos en un laboratorio.','Cambio de nombre de una estructura.','Ausencia de toda actividad muscular.'],'En el texto la palabra se refiere a la forma de moverse caminando sobre dos pies.'),
item('Relación entre ideas','¿Qué aporta la mención de pelvis, columna y músculos?','Ejemplifica la participación de múltiples estructuras.',['Presenta una lista completa de todos los tejidos.','Niega las ventajas descritas antes.','Separa de forma absoluta anatomía y función.'],'La enumeración sostiene la afirmación de que el cambio no se reduce a una sola pieza.')])

read('jerarquia','Un conjunto de niveles relacionados',
'Como comparación didáctica, puede pensarse en un texto formado por párrafos, oraciones y palabras. Cada nivel integra unidades de otro nivel sin confundirse por completo con ellas. La organización del cuerpo presenta una relación semejante: el organismo incluye sistemas de órganos; los órganos reúnen tejidos; los tejidos contienen células, y estas poseen componentes menores.\n\nLa jerarquía permite ordenar el estudio desde el conjunto hasta sus partes. No es una lista de objetos independientes que solo coinciden en el mismo lugar. Un sistema agrupa órganos que participan en una función colectiva, mientras que un órgano integra distintos tejidos. Distinguir estos niveles ayuda a formular preguntas adecuadas: estudiar un tejido no equivale a estudiar un sistema completo. La comparación con el lenguaje sirve para reconocer cómo unidades relativamente simples se integran en organizaciones más complejas, sin afirmar que un cuerpo sea literalmente un escrito.',[40,41],'La jerarquía de la complejidad',[
item('Idea principal','¿Qué explica la lectura?','La organización del cuerpo mediante niveles que integran unidades menores.',['Una equivalencia literal entre palabras y células.','Una lista de estructuras sin relaciones entre ellas.','La necesidad de estudiar todos los niveles como si fueran iguales.'],'Los dos párrafos presentan una jerarquía en la que las partes participan en organizaciones mayores.'),
item('Información explícita','¿Qué reúne un órgano según el texto?','Distintos tejidos.',['Varios organismos completos.','Únicamente sistemas de órganos.','Solo palabras y oraciones.'],'La relación órgano–tejidos se afirma de manera directa en el segundo párrafo.'),
item('Inferencia','¿Por qué estudiar un tejido no equivale a estudiar un sistema completo?','Porque corresponden a niveles diferentes de organización.',['Porque los tejidos no pertenecen al cuerpo.','Porque los sistemas carecen de funciones.','Porque un órgano no puede contener tejidos.'],'La diferencia se deduce de la jerarquía que integra tejidos en órganos y órganos en sistemas.'),
item('Vocabulario en contexto','¿Qué significa «integra» en el pasaje?','Reúne unidades en un conjunto.',['Elimina las diferencias de toda parte.','Separa algo definitivamente.','Nombra un objeto sin describirlo.'],'El término expresa la relación entre unidades menores y niveles de organización mayores.'),
item('Relación entre ideas','¿Qué función cumple la comparación con el lenguaje?','Facilitar la comprensión de una organización por niveles.',['Probar que los órganos están hechos de palabras.','Sustituir el estudio del cuerpo por gramática.','Negar que existan funciones colectivas.'],'La lectura identifica la comparación como didáctica y rechaza una identidad literal.')])

read('celulas','La unidad no es una pieza cualquiera',
'Una célula es la unidad más pequeña del organismo que realiza las funciones básicas de la vida. En su interior existen estructuras con tareas particulares, llamadas organelos. Estos son componentes importantes, pero nombrarlos no significa colocarlos en el mismo nivel organizativo que la célula completa. Los organelos, a su vez, contienen moléculas, y las moléculas están formadas por átomos.\n\nEsta distinción evita confundir la importancia de una parte con la autonomía del conjunto. Una estructura puede ser indispensable para ciertas actividades sin reunir por sí sola todas las funciones que caracterizan a una célula. Al estudiar el cuerpo conviene preguntar no solo qué componente se observa, sino a qué nivel pertenece y cómo participa en una unidad mayor. El detalle de las partes ayuda a comprender la organización, siempre que no se pierda la relación entre sus funciones y la actividad celular.',[41],'Células, organelos y moléculas',[
item('Idea principal','¿Qué distinción sostiene la lectura?','La célula completa y sus componentes pertenecen a niveles diferentes.',['Todo organelo constituye por sí solo un organismo completo.','Las moléculas están formadas por células enteras.','La importancia de una parte elimina la necesidad del conjunto.'],'El texto diferencia la célula como unidad de vida de los componentes que participan en ella.'),
item('Información explícita','¿Cómo se llaman las estructuras celulares con tareas particulares?','Organelos.',['Sistemas de organismos.','Moléculas de tejido completo.','Átomos autónomos.'],'El primer párrafo introduce el nombre y lo vincula con funciones particulares dentro de la célula.'),
item('Inferencia','¿Qué conclusión es coherente con el segundo párrafo?','Una parte importante no necesariamente realiza por sí sola todas las funciones celulares.',['Toda parte importante puede vivir de forma independiente.','Si una parte es pequeña, carece de función.','El estudio de componentes impide comprender la organización.'],'La lectura separa la importancia de una estructura de la autonomía de la unidad completa.'),
item('Vocabulario en contexto','¿Qué significa «autonomía» en esta lectura?','Capacidad de actuar como unidad por sí misma.',['Tamaño microscópico.','Presencia obligatoria de un nombre.','Pertenencia a una molécula.'],'Se contrasta una parte del conjunto con la célula que reúne las funciones básicas.'),
item('Relación entre ideas','¿Qué función tiene la recomendación de preguntar por el nivel?','Evitar que se confundan componentes y unidades de organización.',['Hacer irrelevante la función de cada parte.','Cambiar el tema hacia la historia de los nombres.','Dar a todos los componentes la misma autonomía.'],'La recomendación aplica la distinción conceptual desarrollada desde el inicio.')])

read('reduccionismo','Desarmar para entender',
'El reduccionismo propone que un sistema complejo puede comprenderse estudiando sus componentes más simples. Este enfoque ha sido productivo porque permite investigar partes que resultan más accesibles que el conjunto. Conocer moléculas, células o tejidos ayuda a explicar la organización y el funcionamiento corporal. No obstante, la utilidad de estudiar partes no demuestra que baste con enumerarlas.\n\nEl texto utiliza la comparación con una transmisión de automóvil: observar sus piezas desensambladas no permite reconocer con facilidad todo su funcionamiento. La comparación didáctica señala la importancia de las relaciones entre componentes. Comprender un sistema exige atender también a su organización y a los efectos de la interacción. Por eso, reconocer límites del reduccionismo no obliga a desechar el análisis de partes. Permite situarlo dentro de una explicación más amplia, capaz de relacionar el detalle con el conjunto al que pertenece.',[41,42],'Reduccionismo y holismo',[
item('Idea principal','¿Qué postura presenta el pasaje?','Estudiar partes es útil, pero debe relacionarse con la organización del conjunto.',['El análisis de componentes nunca ha sido productivo.','Enumerar piezas explica necesariamente todo el sistema.','Las partes no tienen relación con el funcionamiento.'],'La lectura reconoce el valor del enfoque reduccionista y luego delimita su alcance.'),
item('Información explícita','¿Qué propone el reduccionismo?','Comprender un sistema complejo mediante sus componentes más simples.',['Estudiar un sistema sin considerar ninguna parte.','Reemplazar todos los componentes por una analogía.','Negar el valor de investigar células y moléculas.'],'La primera oración define expresamente el enfoque.'),
item('Inferencia','¿Qué falta en una simple enumeración de piezas?','La explicación de cómo se organizan e interactúan.',['El nombre de todos los autores.','La garantía de que ninguna pieza es importante.','La demostración de que no existe sistema.'],'El contraste entre piezas aisladas y funcionamiento apunta a las relaciones entre componentes.'),
item('Vocabulario en contexto','¿Qué significa «desechar» en el último párrafo?','Abandonar como inútil.',['Examinar con mayor aumento.','Ordenar alfabéticamente.','Unir físicamente dos piezas.'],'La lectura afirma que reconocer límites no obliga a abandonar el análisis de partes.'),
item('Relación entre ideas','¿Para qué se emplea la transmisión del automóvil?','Para ilustrar el límite de observar componentes separados.',['Para sostener que el cuerpo es literalmente un vehículo.','Para negar que las máquinas tengan piezas.','Para explicar una técnica de reparación de autos.'],'La comparación está presentada como recurso didáctico y no como equivalencia literal.')])

read('holismo','La persona y sus relaciones',
'El holismo complementa el estudio de las partes al señalar que el conjunto presenta propiedades que no se anticipan fácilmente desde componentes separados. En el cuidado de la salud, esta perspectiva invita a considerar a la persona y no únicamente un órgano o una enfermedad. Las percepciones, las respuestas emocionales y la confianza en el profesional pueden influir en el proceso de atención descrito por el texto.\n\nConsiderar esos factores no exige negar la importancia de estructuras y mecanismos corporales. Significa reconocer que una explicación limitada a una parte puede dejar fuera relaciones relevantes del conjunto. El enfoque holístico y el análisis detallado pueden colaborar cuando se evita convertir a cualquiera de ellos en una respuesta exclusiva. La tarea consiste en comprender cómo las distintas dimensiones se relacionan, en lugar de asumir que estudiar una obliga a ignorar las demás.',[42],'Reduccionismo y holismo',[
item('Idea principal','¿Cuál es la idea principal?','La atención al conjunto puede complementar el análisis de partes.',['Los órganos deben dejar de estudiarse.','La confianza reemplaza toda explicación corporal.','El holismo y el análisis detallado son siempre incompatibles.'],'La lectura presenta el holismo como complemento y rechaza una elección excluyente.'),
item('Información explícita','¿Qué factor menciona el texto además de órganos y enfermedades?','La confianza en el profesional.',['La cantidad de ilustraciones del libro.','La posición del aula.','El tamaño de un microscopio.'],'La confianza aparece junto con percepciones y respuestas emocionales en el primer párrafo.'),
item('Inferencia','¿Qué postura sería compatible con la lectura?','Estudiar mecanismos corporales y considerar también factores personales relevantes.',['Suponer que cualquier dimensión explica por sí sola todos los casos.','Ignorar las partes porque existe un conjunto.','Eliminar todo contexto para mantener precisión.'],'La conclusión propone relacionar dimensiones en vez de reemplazar una por otra.'),
item('Vocabulario en contexto','En el pasaje, «exclusiva» significa:','Que pretende ser la única respuesta válida.',['Que tiene acceso restringido.','Que se observa sin microscopio.','Que solo existe en una persona.'],'El término describe el error de convertir uno de los enfoques en respuesta única.'),
item('Relación entre ideas','¿Qué función cumple «no exige negar»?','Evitar interpretar el holismo como rechazo de los mecanismos corporales.',['Confirmar que las estructuras son irrelevantes.','Introducir una definición de órgano.','Reemplazar el tema por una clasificación de tejidos.'],'La expresión delimita el alcance del enfoque y mantiene el valor del estudio de las partes.')])

read('vida','Una característica aislada no basta',
'El crecimiento por sí solo no permite distinguir con seguridad un ser vivo de un objeto inanimado. Un cristal también puede aumentar de tamaño. Desde la perspectiva biológica presentada, la vida se reconoce por un conjunto de características, entre ellas la organización, la composición celular y el metabolismo. La comparación invita a mirar relaciones entre propiedades en lugar de escoger una única señal como prueba suficiente.\n\nLos organismos mantienen su organización mediante actividades continuas e intercambios con el entorno. El metabolismo comprende cambios químicos internos y no se reduce a un aumento visible de volumen. Así, dos objetos pueden parecerse en una característica general, como crecer, y diferir en la manera de hacerlo y en la organización que poseen. La pregunta importante no es solo si algo aumenta de tamaño, sino qué procesos sostienen ese cambio y qué otras propiedades lo acompañan.',[43,44],'Características de la vida',[
item('Idea principal','¿Qué sostiene el pasaje?','La vida se comprende mediante un conjunto de propiedades y procesos.',['Todo objeto que crece es necesariamente un ser vivo.','La apariencia externa permite distinguir siempre la vida.','El metabolismo solo significa aumento de volumen.'],'El texto rechaza un criterio aislado y considera organización, células y cambios químicos.'),
item('Información explícita','¿Qué ejemplo se usa de algo que crece sin ser un organismo?','Un cristal.',['Una célula.','Una persona en desarrollo.','Un tejido con metabolismo.'],'El ejemplo aparece en el primer párrafo para cuestionar la suficiencia del crecimiento.'),
item('Inferencia','¿Qué conviene investigar además del aumento de tamaño?','Los procesos que lo producen y las propiedades que lo acompañan.',['Solo si el objeto tiene un nombre biológico.','Únicamente si el cambio puede verse a distancia.','Si todos los objetos crecen al mismo ritmo.'],'La última oración dirige la atención a los procesos y a las propiedades relacionadas.'),
item('Vocabulario en contexto','¿Qué significa «inanimado»?','Que no tiene vida.',['Que aumenta demasiado de tamaño.','Que solo puede verse al microscopio.','Que está compuesto únicamente por células.'],'El pasaje opone objetos inanimados y seres vivos, sin equiparar crecer con estar vivo.'),
item('Relación entre ideas','¿Qué función tiene comparar un cristal con un organismo?','Mostrar que compartir una característica no implica pertenecer a la misma categoría.',['Demostrar que ambos poseen metabolismo idéntico.','Afirmar que ningún organismo crece.','Reemplazar la definición de cristal por la de célula.'],'La comparación evidencia por qué se necesita valorar más de una propiedad.')])

read('desarrollo','Aumentar de tamaño y adquirir una tarea',
'El desarrollo comprende cambios en la forma o en la función a lo largo de la vida. Incluye procesos relacionados, pero distinguibles: el crecimiento y la diferenciación. Crecer supone aumentar de tamaño; diferenciarse implica que células sin una función especializada se relacionen con tareas específicas. Un cambio puede interesar por su dimensión y otro por la función que aparece.\n\nEl crecimiento de un organismo tampoco se explica como una simple acumulación superficial de materia. En un cristal que crece se agregan moléculas a su superficie; en el cuerpo, el aumento se vincula con modificaciones químicas del material que se incorpora. La comparación didáctica no pretende negar que ambos cambien de tamaño, sino mostrar que la semejanza visible puede ocultar procesos diferentes. Usar con precisión los términos crecimiento, diferenciación y desarrollo ayuda a describir qué clase de cambio se está examinando.',[44],'Características de la vida: desarrollo',[
item('Idea principal','¿Qué diferencia central propone la lectura?','El desarrollo abarca cambios de tamaño y especialización que no son equivalentes.',['Diferenciación y crecimiento significan exactamente lo mismo.','Todo aumento corporal ocurre solo por acumulación superficial.','El desarrollo se refiere únicamente a nombres nuevos.'],'Se distinguen procesos dentro del desarrollo y se compara la manera de crecer de cuerpos y cristales.'),
item('Información explícita','¿A qué se refiere la diferenciación?','A la adquisición de funciones especializadas por células.',['A un aumento de tamaño sin cambio funcional.','A la simple agregación de moléculas en un cristal.','A la desaparición de toda tarea celular.'],'El primer párrafo define el proceso por su relación con tareas específicas.'),
item('Inferencia','Si interesa qué tarea especializada adquiere una célula, ¿qué concepto resulta más adecuado?','Diferenciación.',['Crecimiento entendido solo como tamaño.','Acumulación superficial de un cristal.','Ausencia de desarrollo.'],'La pregunta trata de especialización funcional, no de medir un aumento de tamaño.'),
item('Vocabulario en contexto','¿Qué significa «incorpora»?','Integra o añade al organismo.',['Elimina sin modificar.','Convierte en un nombre técnico.','Separa de todo proceso químico.'],'El término se refiere al material que entra en procesos de crecimiento corporal.'),
item('Relación entre ideas','¿Por qué se comparan el cristal y el cuerpo?','Para distinguir procesos diferentes detrás de un aumento visible.',['Para afirmar que todo crecimiento es idéntico.','Para negar los cambios químicos del cuerpo.','Para sostener que los cristales se diferencian en células.'],'La comparación tiene una finalidad explicativa que el segundo párrafo expresa de forma directa.')])

read('referencia','Un valor característico tiene contexto',
'Los valores fisiológicos no son idénticos en todas las personas y condiciones. La edad, la actividad, la dieta y el entorno pueden acompañarse de diferencias. Por eso, cuando un texto introductorio ofrece un valor característico, es importante reconocer a qué situación o población se refiere. Un ejemplo de referencia permite organizar el aprendizaje, pero no describe sin excepción a cada individuo.\n\nLa variación fisiológica obliga a interpretar los datos con atención al contexto. Utilizar una cifra general como si bastara para representar a cualquier persona puede conducir a errores. Esto no vuelve inútiles los valores de referencia: delimita su alcance. Aprender una cifra y comprender sus condiciones de aplicación son tareas relacionadas. La lectura propone conservar ambas, evitando tanto creer que todas las personas deben coincidir exactamente con un ejemplo como suponer que, por existir variaciones, ninguna referencia puede ayudar a comprender.',[44],'Variación fisiológica',[
item('Idea principal','¿Qué plantea el texto sobre los valores característicos?','Son útiles, pero deben interpretarse dentro de su contexto.',['Describen sin excepción a cada persona.','Carecen de toda utilidad porque existe variación.','Solo cambian cuando el libro tiene errores.'],'La lectura mantiene el valor de las referencias y delimita la generalización de sus cifras.'),
item('Información explícita','¿Cuál de estos factores se menciona como relacionado con diferencias fisiológicas?','La edad.',['La cantidad de capítulos de un atlas.','El orden de las letras de un nombre.','La posición de una palabra en un diccionario.'],'La edad se enumera junto con actividad, dieta y entorno.'),
item('Inferencia','¿Qué conviene preguntar al leer una cifra de referencia?','En qué condiciones y para qué población se presenta.',['Por qué tiene que coincidir exactamente con toda persona.','Cómo evitar considerar la actividad o el entorno.','Por qué reemplaza cualquier otra información.'],'La referencia adquiere alcance al identificar su situación y población.'),
item('Vocabulario en contexto','¿Qué significa «delimita su alcance»?','Precisa hasta dónde puede aplicarse.',['Demuestra que nunca es útil.','Impide registrar un número.','Convierte la variación en una excepción imposible.'],'La expresión distingue establecer límites de negar por completo la utilidad de una referencia.'),
item('Relación entre ideas','¿Qué relación existe entre los dos errores de la última oración?','Son interpretaciones opuestas que la lectura busca evitar.',['Ambos equivalen a interpretar correctamente el contexto.','Uno confirma que no existen variaciones.','Los dos obligan a memorizar más cifras sin comprenderlas.'],'Se rechazan tanto la aplicación universal sin condiciones como el abandono de toda referencia.')])

read('ciclo','Detectar, integrar y responder',
'En un ciclo de retroalimentación pueden reconocerse tres componentes comunes: un receptor, un centro integrador y un efector. El receptor detecta una variación; el centro integra esa información con otra disponible y organiza una respuesta; el efector realiza la acción correspondiente. Los nombres describen tareas diferentes dentro de un proceso relacionado.\n\nEl ejemplo de la regulación de la presión arterial ayuda a seguir la secuencia: la variación es detectada, la información llega a un centro de control y se modifica la actividad del corazón. La respuesta vuelve a ser percibida, de modo que el ciclo no termina simplemente en emitir una orden. La lectura no afirma que todos los mecanismos del cuerpo deban adoptar exactamente esa forma. Presenta un esquema frecuente que permite distinguir quién percibe, cómo se organiza la información y qué estructura ejecuta la respuesta.',[46],'Componentes de un ciclo de retroalimentación',[
item('Idea principal','¿Qué explica el pasaje?','La función de componentes vinculados en un ciclo de retroalimentación.',['Tres nombres intercambiables para una única tarea.','Una secuencia que siempre termina antes de producir respuesta.','Una estructura obligatoriamente idéntica en todo mecanismo corporal.'],'El texto distingue detección, integración y ejecución, y delimita el alcance del esquema.'),
item('Información explícita','¿Qué componente realiza la acción de respuesta?','El efector.',['El nombre del receptor.','La información por sí sola.','El dato de referencia sin una estructura que actúe.'],'La primera parte asigna expresamente al efector la ejecución de la acción.'),
item('Inferencia','¿Qué permite que el proceso se considere un ciclo?','Que la respuesta vuelva a ser percibida por el sistema.',['Que se enumeren tres palabras sin relación.','Que nunca cambie ninguna condición.','Que la información no llegue al centro integrador.'],'El segundo párrafo explica el cierre del ciclo al percibir el resultado de la respuesta.'),
item('Vocabulario en contexto','En este texto, «integra» significa:','Relaciona información para organizar una respuesta.',['Ejecuta por sí mismo toda acción muscular.','Elimina cualquier señal recibida.','Percibe sin procesar una variación.'],'La función del centro se distingue de la detección del receptor y de la ejecución del efector.'),
item('Relación entre ideas','¿Qué función cumple la aclaración sobre «todos los mecanismos»?','Evita presentar un esquema frecuente como una regla sin excepciones.',['Niega que existan receptores.','Anula la utilidad del ejemplo anterior.','Afirma que la presión arterial no cambia.'],'La lectura presenta componentes comunes, sin convertirlos en un molde universal.')])

read('amplificacion','La dirección de una respuesta',
'En la retroalimentación negativa, una respuesta se opone a la variación que la activó. En la positiva, en cambio, el proceso amplifica un cambio en la misma dirección. Estas palabras no equivalen simplemente a bueno y malo: nombran relaciones entre una variación inicial y sus efectos posteriores.\n\nDurante el parto, la presión sobre el cuello uterino participa en una secuencia de señales y contracciones que aumenta esa misma presión, hasta que el proceso culmina con el nacimiento. El ejemplo muestra una amplificación que cumple una función. Sin embargo, un ciclo que se refuerza a sí mismo también puede alejar condiciones internas de su equilibrio y resultar peligroso. Para comprender una retroalimentación conviene, por tanto, reconocer su dirección y su contexto, en lugar de asignarle una valoración por el sentido cotidiano de las palabras positivo y negativo.',[46,47],'Retroalimentación positiva y cambio rápido',[
item('Idea principal','¿Cuál es el propósito de la lectura?','Distinguir la dirección de la retroalimentación de una valoración de sus efectos.',['Afirmar que todo proceso positivo es beneficioso.','Presentar la retroalimentación negativa como un daño.','Negar que un cambio pueda amplificarse.'],'La definición inicial y los ejemplos separan los nombres del mecanismo de las palabras bueno y malo.'),
item('Información explícita','¿Qué hace una retroalimentación positiva?','Amplifica el cambio en la misma dirección.',['Se opone siempre a cualquier variación.','Elimina toda respuesta del organismo.','Impide que una secuencia culmine.'],'La primera parte define la autoamplificación como su relación característica.'),
item('Inferencia','¿Por qué el nombre «positiva» no garantiza un beneficio?','Porque una amplificación puede cumplir una función o alejar condiciones del equilibrio.',['Porque el nombre describe únicamente emociones.','Porque todo cambio amplificado es idéntico al parto.','Porque no se puede reconocer su dirección.'],'El segundo párrafo ofrece tanto una función como una posibilidad de peligro.'),
item('Vocabulario en contexto','¿Qué significa «culmina»?','Llega a su término.',['Empieza a detectarse.','Se opone a todo cambio.','Se convierte en una señal sin efecto.'],'La palabra alude al final del proceso descrito, el nacimiento.'),
item('Relación entre ideas','¿Para qué sirve el ejemplo del parto?','Para mostrar que la amplificación puede participar en una función normal.',['Para definir toda retroalimentación como peligrosa.','Para afirmar que no hay señales en el proceso.','Para cambiar el tema a una recomendación clínica individual.'],'El ejemplo ilustra una función de la retroalimentación positiva sin convertirla en una valoración universal.')])

read('eponimos','Cuando un nombre dice poco',
'Algunos nombres médicos provienen de las personas a quienes se quiso recordar. Esos términos se llaman epónimos y pueden conservar una historia, pero no siempre describen la estructura o el problema que designan. A la dificultad se añade que diferentes lugares han usado nombres distintos para una misma estructura.\n\nLos esfuerzos por uniformar la terminología anatómica responden a esa situación. Un vocabulario compartido facilita que una misma referencia sea reconocida por lectores de contextos distintos. El objetivo no es borrar el pasado de las palabras, sino reducir ambigüedades en la comunicación. Un nombre descriptivo puede aportar información sobre aquello que identifica, mientras que un nombre personal requiere conocer primero a qué se refiere. La lectura invita a distinguir el valor histórico de una denominación y la claridad con que comunica una estructura; ambos criterios no necesariamente coinciden.',[48],'La historia de la terminología anatómica',[
item('Idea principal','¿Qué problema examina el texto?','La relación entre historia de los nombres y claridad de la comunicación anatómica.',['La imposibilidad de compartir nombres entre lectores.','La ausencia de nombres personales en medicina.','La garantía de que todo epónimo describe una estructura.'],'La lectura explica epónimos y relaciona la uniformidad de términos con la reducción de ambigüedades.'),
item('Información explícita','¿De dónde proceden los epónimos?','De nombres de personas.',['Solo del tamaño de un órgano.','De fórmulas químicas.','Siempre de funciones celulares.'],'El primer párrafo define el término a partir de su origen personal.'),
item('Inferencia','¿Qué ventaja puede tener un nombre descriptivo?','Dar información sobre aquello que identifica.',['Asegurar por sí solo que no existen variaciones.','Eliminar la necesidad de estudiar estructuras.','Impedir que alguien de otro contexto lo aprenda.'],'La segunda parte contrasta la información descriptiva con la necesidad de conocer la referencia de un nombre personal.'),
item('Vocabulario en contexto','¿Qué significa «uniformar»?','Establecer denominaciones compartidas.',['Dar a todas las estructuras la misma forma.','Eliminar físicamente diferencias corporales.','Transformar cualquier término en un nombre personal.'],'La uniformidad se refiere a la terminología, no a la anatomía del cuerpo.'),
item('Relación entre ideas','¿Qué distingue la última oración?','El valor histórico de un nombre y su claridad descriptiva.',['Dos nombres de órganos necesariamente diferentes.','La lectura de un libro y la observación de un tejido.','El tamaño de una palabra y el de una estructura.'],'El cierre resume dos criterios que pueden no coincidir al valorar una denominación.')])

read('palabras','Desarmar una palabra para aprenderla',
'Los términos médicos pueden parecer difíciles cuando se estudian como secuencias sin estructura. Muchos, sin embargo, reúnen elementos que se repiten: raíces, prefijos y sufijos. Reconocer esas partes ayuda a relacionar palabras distintas. El significado de una raíz aporta una base; un prefijo o un sufijo puede modificarla.\n\nEsta estrategia facilita la comprensión y la memoria, pero no garantiza que toda palabra se explique completamente por su traducción literal. La historia puede haber desplazado los significados, y los epónimos no se interpretan del mismo modo que una combinación de raíces descriptivas. Por eso conviene usar el análisis de elementos como una herramienta y no como una regla infalible. La ventaja está en descubrir relaciones que reducen la sensación de memorizar nombres aislados, sin dejar de verificar el significado que la palabra tiene en su uso concreto.',[48,49],'Análisis de los términos médicos',[
item('Idea principal','¿Qué propone el texto?','Analizar elementos de las palabras y reconocer los límites de esa estrategia.',['Interpretar todo término exclusivamente por su traducción literal.','Memorizar nombres evitando cualquier relación.','Suponer que todos los epónimos son combinaciones de raíces descriptivas.'],'Se explica una herramienta de aprendizaje y se aclara por qué requiere verificar el significado en contexto.'),
item('Información explícita','¿Qué elementos se mencionan?','Raíces, prefijos y sufijos.',['Órganos, tejidos y células.','Átomos, protones y electrones.','Leyes, teorías y grupos de control.'],'La primera parte enumera esos componentes de muchos términos médicos.'),
item('Inferencia','¿Qué hacer si el sentido literal no coincide con el uso de un término?','Comprobar su significado concreto en vez de imponer la interpretación literal.',['Declarar que la palabra no puede existir.','Dar por hecho que todo uso es incorrecto.','Ignorar cualquier cambio histórico de significado.'],'La advertencia sobre la historia de las palabras exige usar la herramienta sin convertirla en regla absoluta.'),
item('Vocabulario en contexto','¿Qué significa «infalible»?','Que no puede fallar.',['Que requiere demasiadas letras.','Que solo se aplica a prefijos.','Que procede de una persona.'],'El texto niega que el análisis de elementos sea una regla que siempre resuelva el significado.'),
item('Relación entre ideas','¿Qué función cumple «pero no garantiza»?','Introducir un límite después de reconocer una utilidad.',['Rechazar que las raíces se repitan.','Afirmar que no se puede aprender terminología.','Cambiar de tema hacia la fisiología.'],'La expresión mantiene el beneficio de la estrategia y evita prometer resultados universales.')])

read('precision','Una letra puede cambiar la referencia',
'En el lenguaje anatómico, palabras muy parecidas pueden señalar estructuras diferentes. Íleon nombra una parte del intestino delgado, mientras que ilion se refiere a una parte del hueso iliaco. Una variación pequeña en la escritura no implica una diferencia igualmente pequeña en el significado.\n\nLa precisión del lenguaje no es, por eso, un adorno de la presentación. Forma parte de comunicar con claridad aquello que se observa o se estudia. Revisar cómo se escribe y qué significa un término ayuda a evitar que el lector reciba una referencia distinta de la que se quiso transmitir. El cuidado de los detalles se extiende desde la observación del cuerpo hasta su descripción oral y escrita. Aprender términos incluye reconocer diferencias, no solo recordar sonidos parecidos. El ejemplo muestra por qué una corrección aparentemente mínima puede ser necesaria para conservar el sentido de un mensaje.',[50],'La importancia de la precisión',[
item('Idea principal','¿Qué sostiene la lectura?','La precisión de los términos es necesaria para conservar la referencia del mensaje.',['Las palabras parecidas siempre designan la misma estructura.','La ortografía es un adorno sin relación con el significado.','Recordar un sonido reemplaza conocer un término.'],'El ejemplo de íleon e ilion sostiene la importancia de comunicar referencias precisas.'),
item('Información explícita','¿A qué se refiere «íleon» en el texto?','A una parte del intestino delgado.',['A una parte del hueso iliaco.','A cualquier estructura con nombre parecido.','A una técnica de observación.'],'La primera parte distingue de forma expresa las referencias de las dos palabras.'),
item('Inferencia','¿Por qué una corrección de una letra puede ser importante?','Porque puede evitar que el mensaje señale otra estructura.',['Porque toda palabra larga es difícil de leer.','Porque elimina todas las diferencias anatómicas.','Porque convierte una descripción en una observación directa.'],'La magnitud del cambio escrito no determina la magnitud del cambio de significado.'),
item('Vocabulario en contexto','¿Qué significa «referencia» en esta lectura?','La estructura a la que apunta una palabra.',['Una cita bibliográfica obligatoriamente.','Una cifra media de laboratorio.','Un lugar para guardar nombres.'],'El término se usa para señalar aquello que el mensaje identifica.'),
item('Relación entre ideas','¿Qué función cumple el ejemplo inicial?','Dar un caso concreto del problema que se explica después.',['Establecer que todas las palabras se diferencian en una letra.','Definir todos los segmentos intestinales.','Sustituir el tema de comunicación por otro sin relación.'],'Los párrafos posteriores generalizan la lección del contraste entre dos términos.')])

read('agua','Disolver requiere una interacción',
'La molécula de agua tiene una distribución desigual de cargas: el lado del oxígeno es relativamente negativo y el de los hidrógenos, relativamente positivo. Esa polaridad ayuda a explicar su interacción con sustancias cargadas o polares. Cuando una sal se disuelve, las moléculas de agua se orientan alrededor de los iones y contribuyen a mantenerlos separados en la solución.\n\nLlamar al agua un solvente muy eficaz no significa que disuelva cualquier sustancia por igual. El texto distingue las sustancias que se disuelven en agua de las que no lo hacen con facilidad. Su capacidad de solvente favorece el transporte y las reacciones de muchas sustancias en el organismo. La lectura conecta una característica de la molécula con efectos de mayor escala: la distribución de cargas permite comprender interacciones que, a su vez, ayudan a explicar procesos biológicos.',[79],'El agua: polaridad y capacidad de solvente',[
item('Idea principal','¿Cuál es la idea principal?','La polaridad del agua ayuda a explicar su capacidad de interactuar y disolver sustancias.',['El agua carece de distribución de cargas.','Todas las sustancias se disuelven de la misma manera.','La capacidad de solvente no se relaciona con procesos biológicos.'],'El texto pasa de una propiedad molecular a la disolución y sus efectos en el organismo.'),
item('Información explícita','¿Qué ocurre alrededor de los iones al disolverse una sal?','Las moléculas de agua se orientan alrededor de ellos.',['Los iones dejan necesariamente de existir.','Las moléculas de agua pierden todos sus átomos.','Los iones se convierten en células.'],'La descripción de la disolución menciona esa orientación que contribuye a separar iones.'),
item('Inferencia','¿Qué interpretación sería incorrecta?','Que ser un solvente eficaz obliga al agua a disolver todo por igual.',['Que la distribución de cargas influye en interacciones.','Que disolver puede favorecer el transporte.','Que una propiedad molecular puede tener efectos biológicos.'],'La segunda parte rechaza de manera explícita la universalización de su capacidad de solvente.'),
item('Vocabulario en contexto','¿Qué significa «polaridad» en el pasaje?','Distribución desigual de cargas en la molécula.',['Cantidad total de moléculas por litro.','Capacidad de crecer por acumulación.','Relación entre una célula y sus organelos.'],'El primer párrafo vincula la palabra con regiones relativamente negativas y positivas.'),
item('Relación entre ideas','¿Cómo se organiza la explicación?','Relaciona una característica molecular con interacciones y efectos biológicos.',['Enumera datos sin mostrar relaciones.','Parte de una conclusión para negar toda propiedad molecular.','Solo compara nombres de sustancias.'],'El cierre explicita ese recorrido entre escalas de explicación.')],chapter=2)

read('calor','Absorber calor sin cambiar tanto',
'El agua puede absorber una cantidad de calor sin que su temperatura aumente tanto como la de otras sustancias bajo condiciones comparables. Esta estabilidad térmica se relaciona con su capacidad calorífica y con las interacciones entre sus moléculas. Por eso, recibir calor y aumentar de temperatura no describen exactamente lo mismo.\n\nLa evaporación aporta otro aspecto del problema. Cuando el agua pasa de líquido a vapor, se lleva calor; en el cuerpo, la evaporación del sudor contribuye al enfriamiento. No basta, por tanto, mencionar la presencia de agua sin preguntar qué proceso está ocurriendo. La lectura diferencia la capacidad de amortiguar cambios de temperatura y la pérdida de calor asociada a la evaporación. Ambas propiedades ayudan a comprender la importancia del agua, pero lo hacen mediante relaciones distintas. Distinguirlas evita tratar como equivalentes todos los fenómenos térmicos en los que participa.',[79,80],'Estabilidad térmica del agua',[
item('Idea principal','¿Qué distingue el pasaje?','La capacidad calorífica y la pérdida de calor por evaporación.',['La evaporación y la ausencia de cambios de estado.','La temperatura y el calor como conceptos idénticos.','La presencia de agua y cualquier proceso térmico como equivalentes.'],'El texto explica dos contribuciones distintas del agua a los fenómenos térmicos.'),
item('Información explícita','¿Qué ocurre cuando el agua se evapora?','Se lleva calor.',['Permanece necesariamente en estado líquido.','Deja de participar en el intercambio de calor.','Convierte todos los cambios de temperatura en iguales.'],'El segundo párrafo afirma esa relación y la ejemplifica con el sudor.'),
item('Inferencia','¿Qué pregunta ayuda a comprender la función térmica del agua?','Si está absorbiendo calor o cambiando de estado.',['Solo si está presente, sin considerar procesos.','Cuántos nombres diferentes tiene.','Por qué temperatura y calor deben tratarse como lo mismo.'],'La lectura insiste en identificar el proceso y no limitarse a registrar la presencia de agua.'),
item('Vocabulario en contexto','¿Qué significa «amortiguar»?','Atenuar o hacer menos brusco un cambio.',['Impedir para siempre cualquier intercambio.','Volver idénticas todas las temperaturas.','Producir necesariamente más calor.'],'La palabra alude a reducir la magnitud de los cambios de temperatura, no a eliminarlos por completo.'),
item('Relación entre ideas','¿Qué función cumple el ejemplo del sudor?','Ilustrar el enfriamiento relacionado con la evaporación.',['Definir por sí solo la capacidad calorífica.','Probar que toda agua líquida se evapora de inmediato.','Reemplazar la explicación por un consejo de tratamiento.'],'El ejemplo se utiliza para concretar el segundo proceso térmico descrito.')],chapter=2)

read('mezclas','Lo que una mezcla deja ver',
'Las mezclas en agua pueden distinguirse por características de sus partículas. En una solución, el soluto permanece mezclado al dejarla en reposo y sus partículas son tan pequeñas que no dispersan la luz de manera notable. En un coloide, las partículas son mayores y pueden dispersar la luz, aunque permanecen mezcladas. En una suspensión, las partículas pueden separarse al dejar reposar la mezcla.\n\nEstas categorías se refieren a componentes y propiedades, no siempre a un líquido considerado como una realidad uniforme. La sangre permite reconocer la diferencia: puede describirse como solución de sales, coloide de proteínas y suspensión de células. Una misma muestra incluye, por tanto, componentes que justifican descripciones distintas. Para clasificarla conviene preguntar qué partículas se consideran y cómo se comportan. La apariencia general aporta información, pero no sustituye el análisis de aquello que integra la mezcla.',[80,81],'Soluciones, coloides y suspensiones',[
item('Idea principal','¿Qué sostiene el texto?','La clasificación de mezclas requiere atender a las partículas y puede aplicarse a componentes distintos de una muestra.',['Toda muestra debe pertenecer a una sola categoría sin matices.','La apariencia permite ignorar siempre las partículas.','Un coloide se define porque sus partículas siempre se separan al reposar.'],'Se explican propiedades y luego se usa la sangre para mostrar la coexistencia de componentes clasificables.'),
item('Información explícita','¿Qué puede suceder en una suspensión en reposo?','Las partículas pueden separarse de la mezcla.',['Todas las partículas se vuelven invisibles por definición.','El soluto necesariamente se convierte en agua.','Los componentes dejan de tener propiedades.'],'La separación al reposar distingue a la suspensión en la descripción inicial.'),
item('Inferencia','¿Por qué la sangre admite más de una descripción?','Porque contiene componentes con diferentes comportamientos.',['Porque cualquier clasificación carece de criterios.','Porque las células son iguales a las sales disueltas.','Porque una muestra cambia de nombre de forma arbitraria.'],'El ejemplo relaciona sales, proteínas y células con categorías diferentes.'),
item('Vocabulario en contexto','¿Qué significa «uniforme» en el segundo párrafo?','Sin diferencias relevantes entre sus componentes.',['Con una cantidad conocida de litros.','Con nombres usados por todos los países.','Con partículas obligatoriamente grandes.'],'El texto cuestiona considerar el líquido como si todos sus componentes se comportaran igual.'),
item('Relación entre ideas','¿Para qué se introduce la sangre?','Para ejemplificar una muestra con componentes de varias categorías.',['Para negar lo dicho sobre soluciones.','Para afirmar que toda mezcla contiene células.','Para cambiar a una descripción de la circulación.'],'El ejemplo aplica los criterios de clasificación desarrollados antes.')],chapter=2)

read('concentracion','Misma masa no siempre significa misma cantidad de partículas',
'Una concentración puede expresar la masa de soluto presente en un volumen de solución. Esta forma es útil, pero sustancias con distinta masa molar no contienen el mismo número de moléculas por cada gramo. Por eso, dos soluciones con igual masa de soluto en un volumen determinado pueden diferir en su cantidad de partículas.\n\nLa molaridad considera los moles de soluto por litro de solución. Al relacionar masa y cantidad de sustancia mediante la masa molar, permite preparar concentraciones comparables en número de moléculas por volumen. Esto no convierte a la masa en una medida incorrecta: muestra que distintas medidas responden a preguntas diferentes. Antes de comparar concentraciones es necesario reconocer qué se está midiendo y en qué unidades se expresa. Compartir una cifra no basta para afirmar que dos soluciones tienen la misma cantidad de partículas si la forma de medir y las sustancias no se consideran.',[81,82],'Medidas de concentración y molaridad',[
item('Idea principal','¿Qué explica la lectura?','Por qué comparar concentraciones requiere distinguir masa y cantidad de sustancia.',['Por qué la masa de un soluto nunca puede medirse.','Por qué toda solución con la misma cifra contiene iguales partículas.','Por qué molaridad y gramos por litro significan siempre lo mismo.'],'El texto diferencia lo que expresa cada medida y la importancia de la masa molar en la comparación.'),
item('Información explícita','¿Cómo se define la molaridad?','Moles de soluto por litro de solución.',['Gramos de cualquier sustancia sin considerar volumen.','Número de litros por cada molécula.','Masa total del solvente por muestra.'],'La definición aparece en la primera oración del segundo párrafo.'),
item('Inferencia','Si dos solutos tienen distinta masa molar, ¿qué no puede suponerse a partir de masas iguales?','Que contienen el mismo número de moléculas.',['Que la masa puede expresarse en gramos.','Que se puede medir el volumen de solución.','Que los datos pueden compararse usando unidades adecuadas.'],'El primer párrafo afirma que una misma masa no representa necesariamente igual número de partículas.'),
item('Vocabulario en contexto','¿Qué significa «comparables» en este caso?','Expresadas con un criterio que permite relacionar cantidades de partículas por volumen.',['Químicamente idénticas en todas sus propiedades.','Formadas necesariamente por el mismo soluto.','Presentadas sin unidades.'],'La comparabilidad se refiere al criterio de concentración discutido, no a la identidad total entre soluciones.'),
item('Relación entre ideas','¿Qué función cumple «no convierte a la masa en una medida incorrecta»?','Evita confundir una limitación de comparación con la inutilidad de una medida.',['Rechaza la definición de molaridad.','Asegura que toda cifra significa lo mismo.','Elimina la necesidad de conocer las sustancias.'],'El texto conserva la utilidad de ambas medidas y aclara que responden a preguntas distintas.')],chapter=2)

read('ph','Una escala que cambia por factores',
'El pH permite expresar la concentración de iones hidrógeno mediante una escala logarítmica. En las condiciones acuosas de referencia descritas, un pH menor corresponde a mayor concentración de esos iones. Un cambio de una unidad representa una diferencia de diez veces en su concentración, y no una diferencia lineal de una sola partícula.\n\nPor ejemplo, una solución de pH 4 tiene diez veces la concentración de iones hidrógeno de una de pH 5 y cien veces la de una de pH 6. La distancia entre números de la escala debe interpretarse según esa relación. El cuerpo cuenta con soluciones amortiguadoras que resisten cambios del pH; resistir no equivale a volver imposible cualquier cambio. La lectura relaciona dos precauciones: comprender el tipo de escala antes de comparar cifras y distinguir la capacidad de oponerse a una variación de una supuesta invariabilidad absoluta.',[82,83],'Ácidos, bases y pH',[
item('Idea principal','¿Qué propone la lectura?','Interpretar el pH como escala logarítmica y reconocer el alcance de la amortiguación.',['Tratar cada unidad de pH como una diferencia de una partícula.','Suponer que un amortiguador impide cualquier cambio posible.','Considerar que el pH mayor siempre indica más iones hidrógeno.'],'El texto explica el cambio por factores y luego limita una interpretación absoluta de la amortiguación.'),
item('Información explícita','¿Cuántas veces mayor es la concentración de H⁺ a pH 4 que a pH 6 en el ejemplo?','Cien veces.',['Dos veces.','Diez veces.','Mil veces.'],'El ejemplo indica dos unidades de diferencia, cada una con un factor de diez: 10×10=100.'),
item('Inferencia','¿Por qué no debe interpretarse la escala como lineal?','Porque unidades iguales representan factores de concentración.',['Porque los números de pH no pueden compararse.','Porque toda solución tiene la misma concentración.','Porque una unidad significa siempre un ion adicional.'],'La relación logarítmica representa diferencias multiplicativas en la concentración.'),
item('Vocabulario en contexto','¿Qué significa «resisten» aplicado a los amortiguadores?','Se oponen a los cambios.',['Vuelven imposible toda variación.','Aumentan siempre el cambio inicial.','Eliminan el significado de la escala.'],'El segundo párrafo diferencia resistir de garantizar una invariabilidad absoluta.'),
item('Relación entre ideas','¿Qué tienen en común las dos precauciones del cierre?','Evitan interpretar una expresión sin considerar su significado y alcance.',['Prueban que todas las cifras del cuerpo son constantes.','Sustituyen las definiciones por opiniones.','Niegan que puedan existir cambios de pH.'],'En ambos casos se corrige una lectura excesivamente literal o simplificada de lo que se afirma.')],chapter=2)

